using System;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Collections.Generic;using D=System.Collections.Generic.Dictionary<string,object>;
namespace OreumMok {partial class MainForm {
internal void ValidateAssistant(string dir){ShowPage("assistant");Application.DoEvents();var buttons=FindControls(content).OfType<Button>().ToList();var review=buttons.First(x=>x.Text.StartsWith("무료"));review.PerformClick();Application.DoEvents();var output=FindControls(content).OfType<TextBox>().First(x=>x.ReadOnly);if(!output.Text.Contains("규칙 기반")||!output.Text.Contains("AI에 전송"))throw new Exception("Assistant native review failed");using(var bmp=new Bitmap(Width,Height)){DrawToBitmap(bmp,new Rectangle(0,0,Width,Height));bmp.Save(System.IO.Path.Combine(dir,"native-assistant.png"));}System.IO.File.WriteAllText(System.IO.Path.Combine(dir,"assistant-test.json"),"{\"nativeReview\":true,\"liveAiConnected\":false}");}
static IEnumerable<Control> FindControls(Control c){foreach(Control x in c.Controls){yield return x;foreach(Control y in FindControls(x))yield return y;}}
internal void AssistantWorkspace(){
 var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=6};
 foreach(int h in new[]{62,44,82,64,48})layout.RowStyles.Add(new RowStyle(SizeType.Absolute,h));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));content.Controls.Add(layout);
 layout.Controls.Add(new Label{Dock=DockStyle.Fill,Text="무료 자동검토는 즉시 사용할 수 있습니다. 생성형 AI는 무료 프로젝트 API 연결이 필요합니다.\nAI 답변은 견적 확정·구조 안전 승인·전기 검사를 대신하지 않습니다.",ForeColor=Style.Muted},0,0);
 var choices=new ComboBox{Dock=DockStyle.Fill,DropDownStyle=ComboBoxStyle.DropDownList};var specs=new List<D>{J.Row("kind","general","id","")};choices.Items.Add("일반 시공 질문 / 계단 점검");
 foreach(string key in new[]{"quotes","lighting","designs"})if(Can(key+".read"))foreach(D row in J.Rows(state,key)){specs.Add(J.Row("kind",key,"id",J.Text(row,"id")));choices.Items.Add((key=="quotes"?"견적: ":key=="designs"?"3D 설계: ":"조명: ")+J.Text(row,"name"));}choices.SelectedIndex=0;layout.Controls.Add(choices,0,1);
 var question=new TextBox{Dock=DockStyle.Fill,Multiline=true,MaxLength=2000,ScrollBars=ScrollBars.Vertical,Text="이 공사에서 견적에 빠지기 쉬운 항목과 시공 전 확인사항을 정리해 주세요."};layout.Controls.Add(question,0,2);
 var consent=new CheckBox{Dock=DockStyle.Fill,Text="질문과 아래 검토 수치를 외부 Gemini AI에 전송하는 데 동의합니다.\n고객 이름·주소·전화번호를 질문에 적지 마세요. 무료 API 입력은 제공업체의 서비스 개선에 쓰일 수 있습니다."};layout.Controls.Add(consent,0,3);
 var bar=new FlowLayoutPanel{Dock=DockStyle.Fill};layout.Controls.Add(bar,0,4);var output=new TextBox{Dock=DockStyle.Fill,ReadOnly=true,Multiline=true,ScrollBars=ScrollBars.Vertical,Font=new Font(Premium.Family,11)};layout.Controls.Add(output,0,5);
 D reviewed=null;string reviewedKey="";Func<string> selection=()=>J.S.Serialize(specs[choices.SelectedIndex]);
 choices.SelectedIndexChanged+=(s,e)=>{reviewed=null;reviewedKey="";output.Text="대상이 바뀌었습니다. 무료 자동검토를 먼저 실행하세요.";consent.Checked=false;};
 bar.Controls.Add(Style.Button("무료 자동검토 · 전송 자료 확인",(s,e)=>{try{LoadState();reviewed=b.Call("assistantReview",specs[choices.SelectedIndex]);reviewedKey=selection();var notes=((System.Collections.IEnumerable)reviewed["notes"]).Cast<object>().Select(Convert.ToString);output.Text=J.Text(reviewed,"notice")+"\r\n\r\n"+String.Join("\r\n\r\n",notes)+"\r\n\r\n[AI에 전송할 수치 자료]\r\n"+J.S.Serialize(reviewed["context"]);consent.Checked=false;}catch(Exception ex){output.Text=ex.Message;}}));
 var ask=Style.Button("생성형 AI 질문",async(s,e)=>{if(reviewed==null||reviewedKey!=selection()){output.Text="먼저 무료 자동검토로 전송할 자료를 확인하세요.";return;}if(!consent.Checked){MessageBox.Show("외부 AI 전송에 동의해 주세요.");return;}var args=J.Clone(specs[choices.SelectedIndex]);args["question"]=question.Text;args["consent"]=true;args["previewToken"]=J.Text(reviewed,"previewToken");bar.Enabled=false;question.Enabled=false;choices.Enabled=false;try{var status=b.Call("assistantStatus");if(!J.Bool(status,"configured")){output.AppendText("\r\n\r\n"+J.Text(status,"notice")+"\r\n현재 생성형 AI는 미연결 상태입니다.");return;}var result=await System.Threading.Tasks.Task.Run(()=>b.Call("assistantAsk",args));if(!output.IsDisposed)output.Text=J.Text(result,"answer")+"\r\n\r\n"+J.Text(result,"notice");}catch(Exception ex){if(!output.IsDisposed)output.AppendText("\r\n\r\n"+ex.Message);}finally{if(!bar.IsDisposed){bar.Enabled=true;question.Enabled=true;choices.Enabled=true;}}});bar.Controls.Add(ask);
 }
}}
